// ---------------------------------------------------------------------------
// The Solytiq Cloud app-icon mark, inlined as a base64 data URI for use in
// transactional emails. Embedded directly (rather than referenced via an
// absolute URL) so the logo always renders regardless of whether PUBLIC_URL/
// FRONTEND_URL is configured on this instance, and regardless of an email
// client's remote-image-loading policy. Sourced from
// frontend/public/icons/icon-192.png — the same flattened, opaque
// (no-transparency) square already generated for the iOS Home Screen icon
// (see CLAUDE.md's "Home Screen Install" section for why it's flattened
// onto the brand primary rather than the raw transparent-corner logo file).
// Regenerate this constant the same way if the source logo ever changes:
// `base64 -w0 frontend/public/icons/icon-192.png`.
// ---------------------------------------------------------------------------

export const LOGO_DATA_URI = 'data:image/png;base64,';
